/* Sitemap page */
.sitemap-list ul.children {
    margin-left: 1.5rem;
    margin-top: 0.5rem;
    margin-bottom: 0.5rem;
    padding-left: 1rem;
    border-left: 2px solid #e2e8f0;
}
.sitemap-list li { margin-bottom: 0.5rem; }
.sitemap-list a {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    color: #475569;
    transition: color 0.2s;
}
.sitemap-list a:hover { color: var(--color-brand, #10b981); }
.sitemap-list a::before {
    content: "\f105";
    font-family: "Font Awesome 6 Free";
    font-weight: 900;
    font-size: 0.75rem;
    color: #cbd5e1;
}

.tonkla-hp-field {
    position: absolute;
    left: -9999px;
    height: 0;
    overflow: hidden;
}
